'use strict';
// Independent equivalent vertical supports, not a reconstruction of the undisclosed bogie.
const rideDefaults={enabled:true,terrain:[0,0,15,0,0],swivel:[0,0,180],wire:4.5,mean:42,activeCoils:5.5,freeLength:85,preload:60,travel:35,extension:14,driveK:350,frontTireK:180,rearK:250,ax:0,mu:.55};
const freshRide=()=>({...rideDefaults,terrain:[...rideDefaults.terrain],swivel:[...rideDefaults.swivel]});
let rideDesign=freshRide(),rideCache=null;
const rideNames=['D-L 구동','D-R 구동','C-L 전방','C-R 전방','C-3 후방'];
function rideSpring(c=rideDesign){const G=79000,k=G*c.wire**4/(8*c.mean**3*c.activeCoils),total=c.activeCoils+2,solid=total*c.wire,index=c.mean/c.wire,wahl=(4*index-1)/(4*index-4)+.615/index;return{k,total,solid,index,wahl,preCompression:c.preload/k,maxStrokeBeforeSolid:c.freeLength-solid-c.preload/k,stress:force=>wahl*8*force*c.mean/(Math.PI*c.wire**3)};}
function rideLocations(c=rideDesign,p=params){const front=p.L/2-70,cy=p.W/2-80,rear=-p.L/2+54,theta=c.swivel.map(v=>v*Math.PI/180);return[[0,p.T/2,p.D/2],[0,-p.T/2,p.D/2],...theta.slice(0,2).map((a,i)=>[front-20*Math.cos(a),(i===0?1:-1)*cy-20*Math.sin(a),37.5]),[rear-16*Math.cos(theta[2]),-16*Math.sin(theta[2]),32.5]];}
function rideSpecs(c=rideDesign,p=params){return rideLocations(c,p).map((point,i)=>({name:rideNames[i],point,front:i===2||i===3,tire:i<2?c.driveK:i===4?c.rearK:c.frontTireK,offset:i===2||i===3?c.extension:0}));}
function rideBranches(w,c){if(!w.front)return[{min:-Infinity,max:0,k:0,b:0,state:'air'},{min:0,max:Infinity,k:w.tire,b:0,state:'tire'}];const k=rideSpring(c).k,t=w.tire,lo=c.preload/t,hi=c.travel+(c.preload+k*c.travel)/t;return[{min:-Infinity,max:0,k:0,b:0,state:'air'},{min:0,max:lo,k:t,b:0,state:'droop-stop'},{min:lo,max:hi,k:k*t/(k+t),b:c.preload*t/(k+t),state:'spring'},{min:hi,max:Infinity,k:t,b:-t*c.travel,state:'bump-stop'}];}
function rideLinearSolve(A,b){const q=A.map((r,i)=>[...r,b[i]]);for(let i=0;i<3;i++){let best=i;for(let j=i+1;j<3;j++)if(Math.abs(q[j][i])>Math.abs(q[best][i]))best=j;if(Math.abs(q[best][i])<1e-9)return null;[q[i],q[best]]=[q[best],q[i]];const pivot=q[i][i];for(let k=i;k<4;k++)q[i][k]/=pivot;for(let j=0;j<3;j++)if(j!==i){const m=q[j][i];for(let k=i;k<4;k++)q[j][k]-=m*q[i][k];}}return q.map(r=>r[3]);}
function solveRide(c=rideDesign,p=params,load=massAnalysis()){
 const wheels=rideSpecs(c,p),W=load.total*9.81,xEffective=load.cg[0]-c.ax/9.81*load.cg[2],E=[W,W*xEffective/300,W*load.cg[1]/300],B=wheels.map(w=>[1,w.point[0]/300,w.point[1]/300]),branches=wheels.map(w=>rideBranches(w,c)),offset=wheels.map((w,i)=>w.offset+c.terrain[i]);let result=null,examined=0;
 function check(chosen){examined++;const A=Array.from({length:3},()=>[0,0,0]),rhs=E.map(v=>-v);chosen.forEach((s,i)=>{for(let j=0;j<3;j++){rhs[j]+=B[i][j]*(s.k*offset[i]+s.b);for(let k=0;k<3;k++)A[j][k]+=s.k*B[i][j]*B[i][k];}});const q=rideLinearSolve(A,rhs);if(!q)return;const rows=wheels.map((w,i)=>{const s=chosen[i],body=q.reduce((sum,v,j)=>sum+v*B[i][j],0),deflection=offset[i]-body,force=s.k*deflection+s.b;return{...w,index:i,body,deflection,force,state:s.state,ground:c.terrain[i],spring:w.front?Math.max(0,Math.min(c.travel,(force-c.preload)/rideSpring(c).k)):0,tireDeflection:Math.max(0,force/w.tire),gap:Math.max(0,-deflection),valid:deflection>=s.min-1e-7&&deflection<=s.max+1e-7&&force>=-1e-6};});if(!rows.every(r=>r.valid))return;rows.forEach(r=>{r.force=Math.max(0,r.force);r.contact=r.force>1e-5;r.stopForce=r.state==='bump-stop'?Math.max(0,r.force-(c.preload+rideSpring(c).k*c.travel)):r.state==='droop-stop'?Math.max(0,c.preload-r.force):0;});
  const residual=E.map((e,j)=>rows.reduce((s,r,i)=>s+r.force*B[i][j],0)-e),hull=convexHull(rows.filter(r=>r.contact).map(r=>r.point.slice(0,2)));if(hull.length<3||residual.some(v=>Math.abs(v)>1e-4))return;
  const margin=Math.min(...hull.map((a,i)=>{const b=hull[(i+1)%hull.length];return((b[0]-a[0])*(load.cg[1]-a[1])-(b[1]-a[1])*(xEffective-a[0]))/Math.hypot(b[0]-a[0],b[1]-a[1]);}));
  const driveNormal=rows[0].force+rows[1].force,traction=c.mu*driveNormal,required=Math.abs(load.total*c.ax+.02*W),spring=rideSpring(c);result={ok:true,rows,q,heave:q[0],slopeX:q[1]/300,slopeY:q[2]/300,pitch:Math.atan(q[1]/300)*180/Math.PI,roll:Math.atan(q[2]/300)*180/Math.PI,total:load.total,cg:[...load.cg],xEffective,hull,margin,residual,driveNormal,traction,tractionRequired:required,tractionRatio:traction?required/traction:Infinity,springK:spring.k,solidMargin:Math.min(...rows.filter(r=>r.front).map(r=>c.freeLength-spring.solid-spring.preCompression-r.spring)),modelRange:Math.max(Math.abs(q[1]/300),Math.abs(q[2]/300))<Math.tan(5*Math.PI/180)};
 }
 function enumerate(i,chosen){if(result)return;if(i===5){check(chosen);return;}for(const s of branches[i])enumerate(i+1,[...chosen,s]);}enumerate(0,[]);return result?{...result,examined}:{ok:false,rows:[],total:load.total,cg:[...load.cg],xEffective,examined,reason:'No nonsingular vertical static equilibrium within the assumed unilateral support laws; this is not a tipping trajectory.'};
}
function rideAnalysis(){const load=massAnalysis(),key=JSON.stringify([rideDesign,params,load.total,load.cg]);if(rideCache?.key===key)return rideCache.value;const current=solveRide(rideDesign,params,load),baseline=solveRide({...rideDesign,terrain:[0,0,0,0,0],swivel:[0,0,180],ax:0},params,load);if(current.ok&&baseline.ok)current.rows.forEach((r,i)=>{r.deltaSpring=r.spring-baseline.rows[i].spring;r.deltaTire=r.tireDeflection-baseline.rows[i].tireDeflection;r.bodyDelta=r.body-(baseline.q[0]+baseline.q[1]*r.point[0]/300+baseline.q[2]*r.point[1]/300);});const value={current,baseline};rideCache={key,value};return value;}
function rideCasterState(index){const p=rideLocations()[index],r=rideAnalysis().current;return{point:p,index,yaw:rideDesign.swivel[index===4?2:index-2],delta:r.ok&&rideAnalysis().baseline.ok?r.rows[index].deltaSpring:0};}
function rideCameraClearances(){const a=rideAnalysis(),c=rideDesign;if(!a.baseline.ok)return[];const R=Math.hypot(20+37.5,13);return cameraFrames().map(f=>{const i=f.side>0?2:3,ref=a.baseline.rows[i].spring,lo=-ref,hi=c.travel-ref,kingpin=[params.L/2-70,f.side*(params.W/2-80)],moving=[cameraOBB(mIdentity(),[...kingpin,(lo+hi+96)/2],[R*2,R*2,hi+96-lo],'휠·포크·선회부 전 범위'),cameraOBB(mIdentity(),[...kingpin,169-c.freeLength+rideSpring(c).preCompression-6+c.travel/2],[50,50,c.travel+9],'하부 스프링 시트'),cameraOBB(mIdentity(),[...kingpin,(169-c.freeLength+rideSpring(c).preCompression+169)/2],[rideDesign.mean+rideDesign.wire,rideDesign.mean+rideDesign.wire,c.freeLength-rideSpring(c).preCompression],'코일 포락')],parts=cameraMountOBBs(f),pairs=parts.flatMap(part=>moving.map(other=>({part:part.name,against:other.name,gap:cameraOBBGap(part,other)}))),best=pairs.reduce((a,b)=>a.gap<b.gap?a:b);return{side:f.side,...best,clear:best.gap>=3,overlap:best.gap<0,method:'conservative full-swivel/full-stroke bounding boxes, not exact minimum distance or a confirmed collision'};});}
function rideExport(){const s=rideSpring();return{inputs:{...rideDesign},spring:{rate_N_mm:s.k,totalCoils:s.total,solidLength_mm:s.solid,precompression_mm:s.preCompression,maxStrokeBeforeSolid_mm:s.maxStrokeBeforeSolid},analysis:rideAnalysis(),cameraSweptReservations:rideCameraClearances(),topology:'independent equivalent vertical supports; undisclosed rigid bogie is not active in this mode',limits:['quasi-static linear body-plane model; CG horizontal coordinates fixed for body tilt','equivalent acceleration load transfer, no time integration, damping, impact or tire friction dynamics','camera envelopes enclose full swivel/stroke and can conservatively overlap without an actual collision','spring dimensions and stiffness are candidates, no supplier part selection or fatigue allowable stress']};}
